<script setup>
import {ref} from 'vue';import {useRouter,useRoute,RouterLink} from 'vue-router';import {supabase} from '../services/supabase';import {getMyProfile,isBlockedStatus,signOut,blockedMessage} from '../services/account';
const email=ref(''),password=ref(''),error=ref(''),loading=ref(false),router=useRouter(),route=useRoute();async function login(){loading.value=true;error.value='';try{const {error:e}=await supabase.auth.signInWithPassword({email:email.value.trim(),password:password.value});if(e)throw e;const {profile}=await getMyProfile({force:true});if(isBlockedStatus(profile)){await signOut();throw new Error(blockedMessage(profile))}router.push('/dashboard')}catch(e){error.value=e.message||'Unable to log in.'}finally{loading.value=false}}
</script>
<template><div class="auth-wrap"><section class="auth-brand"><span class="brand-mark">C</span><span class="eyebrow">WELCOME BACK</span><h1>Your next opportunity is still out there.</h1><p>Sign in to pick up where you left off, track applications and discover new ways to grow.</p><div class="muted" style="color:#c8d7e1">WORK. LEARN. GROW.</div></section><section class="auth-panel"><form class="auth-form" @submit.prevent="login"><RouterLink to="/" class="muted">← Back to Campus Gig</RouterLink><h2 style="margin-top:30px">Welcome back</h2><p>Enter your details to access your account.</p><div v-if="route.query.verified" class="alert success">Email verified. You can now sign in.</div><div v-if="error" class="alert error">{{error}}</div><div class="field"><label>Email address</label><input v-model="email" class="input" type="email" autocomplete="email" required placeholder="you@example.com"></div><div class="field"><label>Password</label><input v-model="password" class="input" type="password" autocomplete="current-password" required placeholder="Enter your password"></div><div style="display:flex;justify-content:flex-end;margin:-5px 0 20px"><RouterLink to="/forgot-password" class="muted" style="font-size:12px">Forgot password?</RouterLink></div><button class="btn btn-primary" style="width:100%" :disabled="loading">{{loading?'Signing in…':'Sign in'}}</button><p style="text-align:center;margin-top:22px">New to Campus Gig? <RouterLink to="/register" style="color:var(--green);font-weight:800">Create an account</RouterLink></p></form></section></div></template>
